function syncSabaFromEnv() {
  const gateway = process.env.SABA_GATEWAY;
  const token = process.env.SABA_TOKEN;
  if (!gateway || !token)
    return false;
  store.setPlatform("SABA", {
    gateway,
    token,
    games: getActivePlatformGameIds("SABA").map(String),
  });
  return true;
}

function syncSabaFromSession(session) {
  if (!session?.gateway || !session?.token)
    return false;
  store.setPlatform("SABA", {
    gateway: session.gateway,
    token: session.token,
    games: (session.gameIds || getActivePlatformGameIds("SABA")).map(String),
  });
  return true;
}

function syncHgFromEnv() {
  const gateway = process.env.HG_GATEWAY;
  const token = process.env.HG_TOKEN;
  if (!gateway || !token)
    return false;
  store.setPlatform("HG", {
    gateway,
    token: typeof token === "string" ? token : JSON.stringify(token),
  });
  return true;
}

function syncHgFromSession(session) {
  if (!session?.gateway || !session?.token)
    return false;
  store.setPlatform("HG", {
    gateway: session.gateway,
    token: JSON.stringify(session.token),
  });
  return true;
}

async function ensurePlatformCredentials() {
  store.ensureSeed();
  let obSynced = false;
  obSynced = syncObFromStore();
  if (!obSynced) {
    try {
      await syncObLogin();
      obSynced = true;
    }
    catch (err) {
      console.warn("[platform-sync] OB login failed:", err.message);
    }
  }

  let raySynced = syncRayFromA8();
  if (!raySynced) {
    raySynced = syncRayFromEnv();
  }

  let pbSynced = false;
  try {
    const { tryLoadSession } = requirePlatform("PB", "node", "session.js");
    const session = tryLoadSession();
    if (session)
      pbSynced = syncPbFromSession(session);
  }
  catch (err) {
    console.warn("[platform-sync] PB platforms.json load failed:", err.message);
  }
  if (!pbSynced) {
    pbSynced = syncPbFromEnv();
  }

  let tfSynced = syncTfFromEnv();
  if (!tfSynced) {
    tfSynced = await syncTfFromLocal();
  }

  const iaSynced = syncIaFromEnv() || syncIaFromA8Defaults();

  const imtSynced = syncImtFromEnv();

  const imSynced = syncImFromEnv();
  const xbetSynced = syncXbetFromEnv();
  const stakeSynced = syncStakeFromEnv();
  const sabaSynced = syncSabaFromEnv();
  const hgSynced = syncHgFromEnv();

  return {
    obSynced,
    raySynced,
    pbSynced,
    tfSynced,
    iaSynced,
    imtSynced,
    imSynced,
    xbetSynced,
    stakeSynced,
    sabaSynced,
    hgSynced,
  };
}

export {
  ensurePlatformCredentials,
  resolveObSession,
  syncHgFromEnv,
  syncHgFromSession,
  syncIaFromA8Defaults,
  syncIaFromEnv,
  syncIaFromSession,
  syncImFromEnv,
  syncImtFromEnv,
  syncImtFromSession,
  syncObFromSession,
  syncObFromStore,
  syncObLogin,
  syncPbFromEnv,
  syncPbFromSession,
  syncRayFromA8,
  syncRayFromEnv,
  syncRayFromSession,
  syncSabaFromEnv,
  syncSabaFromSession,
  syncStakeFromEnv,
  syncStakeFromSession,
  syncTfFromLocal,
  syncTfFromEnv,
  syncTfFromSession,
  syncTfFromLocal as syncTfFromA8,
  syncXbetFromEnv,
};

﻿"use strict";

const fs = require("fs");
const path = require("path");
const { ESPORT_DATA_DIR } = require("../backend/_paths.cjs");
const { getActivePlatformGameIds } = require("./_require.js").reqS("catalog/game_catalog");
const Core = require("./core.js");

const PLATFORMS_FILE = path.join(ESPORT_DATA_DIR, "platforms.json");
const DEFAULT_SPORT_PATH = "43";

function normalizeGateway(gateway) {
  return String(gateway || "").replace(/\/+$/, "");
}

function parseGameIdsEnv() {
  const raw = process.env.SABA_GAME_IDS;
  if (raw === "*") return [];
  if (raw) return raw.split(/[,;\s]+/).map((s) => s.trim()).filter(Boolean);
  return getActivePlatformGameIds("SABA");
}

function loadFromPlatformsJson() {
  try {
    if (!fs.existsSync(PLATFORMS_FILE)) return null;
    const all = JSON.parse(fs.readFileSync(PLATFORMS_FILE, "utf8"));
    const row = all.SABA;
    if (!row?.gateway || !row?.token) return null;
    return buildSessionFromRow(row);
  } catch {
    return null;
  }
}

function loadFromEnv() {
  const gateway = process.env.SABA_GATEWAY;
  const token = process.env.SABA_TOKEN;
  if (!gateway || !token) return null;
  return buildSessionFromRow({
    gateway,
    token,
    sportPath: process.env.SABA_SPORT_PATH,
    gameIds: parseGameIdsEnv(),
  });
}

function buildSessionFromRow(row) {
  const gateway = normalizeGateway(row.gateway);
  const sportPath = row.sportPath || process.env.SABA_SPORT_PATH || DEFAULT_SPORT_PATH;
  const pageUrl = `${gateway}/${row.token}/ESports/${sportPath}/ALL?mode=m0&market=L`;
  return {
    provider: "SABA",
    gateway,
    token: row.token,
    sportPath,
    pageUrl,
    gameIds: Array.isArray(row.games) ? row.games.map(String) : parseGameIdsEnv(),
  };
}

function tryLoadSession() {
  return loadFromEnv() || loadFromPlatformsJson();
}

async function fetchEsportsPage(session) {
  const res = await fetch(session.pageUrl, {
    headers: {
      "user-agent":
        process.env.SABA_USER_AGENT ||
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120.0.0.0 Safari/537.36",
    },
  });
  if (!res.ok) {
    throw new Error(`SABA page HTTP ${res.status}`);
  }
  return res.text();
}

async function resolveWsConfig(session) {
  const html = await fetchEsportsPage(session);
  const wsConfig = Core.parseEsportsPage(html);
  if (!wsConfig?.token) {
    throw new Error("SABA 页面解析失败（缺少 url/id/account）");
  }
  const originHost = new URL(session.gateway).host;
  return {
    ...wsConfig,
    origin: `https://${originHost}`,
    checkinUrl: `${session.gateway}/${session.token}/LoginCheckin/Index`,
    session,
  };
}

async function loginCheckin(config) {
  await fetch(config.checkinUrl, {
    method: "POST",
    headers: { username: "" },
  });
}

function persistPlatform(session, wsConfig) {
  try {
    const dir = path.dirname(PLATFORMS_FILE);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    let all = {};
    if (fs.existsSync(PLATFORMS_FILE)) {
      all = JSON.parse(fs.readFileSync(PLATFORMS_FILE, "utf8"));
    }
    all.SABA = {
      gateway: session.gateway,
      token: session.token,
      games: session.gameIds,
      wsHost: wsConfig.wsHost,
      updatedAt: new Date().toISOString(),
    };
    fs.writeFileSync(PLATFORMS_FILE, JSON.stringify(all, null, 2));
  } catch {
    /* ignore */
  }
}

module.exports = {
  tryLoadSession,
  resolveWsConfig,
  loginCheckin,
  persistPlatform,
};

﻿"use strict";

const fs = require("fs");
const path = require("path");
const { ESPORT_DATA_DIR } = require("../backend/_paths.cjs");
const { getDefaultSportIds } = require("./sport_ids.js");
const { getActivePlatformGameIds } = require("./_require.js").reqS("catalog/game_catalog");

const PLATFORMS_FILE = path.join(ESPORT_DATA_DIR, "platforms.json");

function normalizeGateway(gateway) {
  return String(gateway || "").replace(/\/+$/, "");
}

function decodeToken(raw) {
  if (!raw) return null;
  try {
    const json = Buffer.from(String(raw), "base64").toString("utf8");
    return JSON.parse(json);
  } catch {
    return null;
  }
}

function loadFromPlatformsJson() {
  try {
    if (!fs.existsSync(PLATFORMS_FILE)) return null;
    const all = JSON.parse(fs.readFileSync(PLATFORMS_FILE, "utf8"));
    const row = all.IMT;
    if (!row?.gateway || !row?.token) return null;
    return buildSessionFromRow(row);
  } catch {
    return null;
  }
}

function loadFromEnv() {
  const gateway = process.env.IMT_GATEWAY;
  const token = process.env.IMT_TOKEN;
  if (!gateway || !token) return null;
  return buildSessionFromRow({
    gateway,
    token,
    referer: process.env.IMT_REFERER,
    userAgent: process.env.IMT_USER_AGENT,
    xSc: process.env.IMT_X_SC,
    sportIds: parseSportIdsEnv(),
  });
}

function buildSessionFromRow(row) {
  const decoded = decodeToken(row.token);
  return {
    provider: "IMT",
    gateway: normalizeGateway(row.gateway),
    token: row.token,
    tokenPayload: decoded,
    referer: row.referer || process.env.IMT_REFERER || row.gateway,
    userAgent:
      row.userAgent ||
      process.env.IMT_USER_AGENT ||
      "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
    xSc:
      row.xSc ||
      process.env.IMT_X_SC ||
      "AlcIWQJYUwMIBwEFVAkLVAECBw9QVV0BDQpXWAAHAVIABB0DACFIbmFVIlI9BCw6OBBxXANsEzZZ",
    sportIds: Array.isArray(row.sportIds) ? row.sportIds.map(String) : parseSportIdsEnv(),
    fetchedAt: null,
  };
}

function parseSportIdsEnv() {
  const raw = process.env.IMT_SPORT_IDS;
  if (raw === "*") return [];
  if (raw) {
    return raw.split(/[,;\s]+/).map((s) => s.trim()).filter(Boolean);
  }
  const fromCatalog = [...new Set(getActivePlatformGameIds("IMT"))];
  return fromCatalog.length ? fromCatalog : getDefaultSportIds();
}

function tryLoadSession() {
  return loadFromEnv() || loadFromPlatformsJson();
}

function loadSession() {
  const session = tryLoadSession();
  if (!session) {
    throw new Error("缺少 IMT 凭证（IMT_GATEWAY + IMT_TOKEN 或 platforms.json）");
  }
  return session;
}

function buildHeaders(session) {
  const decoded = session.tokenPayload || decodeToken(session.token);
  return {
    "content-type": "application/json; charset=utf-8",
    referer: session.referer,
    "user-agent": session.userAgent,
    "x-isfacelift": "true",
    "x-lang": "hans",
    "x-platform": "1",
    "x-sc": session.xSc,
    "x-token": decoded?.tk || "",
    "x-v": decoded?.v || "",
    "x-viewtype": "1",
  };
}

async function imtPost(session, urlPath, body) {
  const base = session.gateway.replace(/\/$/, "");
  const url = `${base}${urlPath.startsWith("/") ? urlPath : `/${urlPath}`}`;
  const res = await fetch(url, {
    method: "POST",
    headers: buildHeaders(session),
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    throw new Error(`IMT POST ${urlPath} HTTP ${res.status}`);
  }
  const data = await res.json();
  if (data?.StatusCode !== 100) {
    throw new Error(data?.Message || `IMT POST ${urlPath} StatusCode=${data?.StatusCode}`);
  }
  return data;
}

async function fetchAllLiveEvents(session, sportIds) {
  const ids = sportIds?.length ? sportIds : getDefaultSportIds();
  const body = {
    AllLiveEventsRequestGroups: ids.map((id) => ({
      SportId: Number(id),
      EventGroupTypeIds: [],
      OddsTemplateBetType: 0,
      OddsTemplate: 16,
    })),
    IsCombo: false,
    OddsType: 3,
    BetTypes: [283],
    Periods: [1],
    SortingType: 2,
    PanelType: 2,
  };
  return imtPost(session, "/mobilesitev2/api/Event/GetAllLiveEvents", body);
}

async function fetchLiveEventsDelta(session, sportIds, delta) {
  const ids = sportIds?.length ? sportIds : getDefaultSportIds();
  const body = {
    AllLiveEventsDeltaRequestGroups: ids.map((id) => ({
      SportId: Number(id),
      EventGroupTypeIds: [],
      OddsTemplateBetType: 0,
      OddsTemplate: 16,
    })),
    CompetitionIds: [],
    SortingType: 2,
    Delta: delta,
    BetTypes: [283],
    Periods: [1],
    OddsType: 3,
    SportIds: ids.map(Number),
    IsCombo: false,
    PanelType: 2,
  };
  return imtPost(session, "/mobilesitev2/api/Event/getAllLiveEventsDelta", body);
}

function persistPlatform(session) {
  try {
    const dir = path.dirname(PLATFORMS_FILE);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    let all = {};
    if (fs.existsSync(PLATFORMS_FILE)) {
      all = JSON.parse(fs.readFileSync(PLATFORMS_FILE, "utf8"));
    }
    all.IMT = {
      gateway: session.gateway,
      token: session.token,
      referer: session.referer,
      userAgent: session.userAgent,
      xSc: session.xSc,
      sportIds: session.sportIds,
      updatedAt: new Date().toISOString(),
    };
    fs.writeFileSync(PLATFORMS_FILE, `${JSON.stringify(all, null, 2)}\n`);
  } catch (err) {
    console.warn("[imt-session] persist skip:", err.message);
  }
}

module.exports = {
  tryLoadSession,
  loadSession,
  fetchAllLiveEvents,
  fetchLiveEventsDelta,
  persistPlatform,
  decodeToken,
};

